#include <stdio.h>

int main() {
    int n;
    double max = -1.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        if (calificacion > max) {
            max = calificacion;
        }
    }
    if (n >= 2) {
        printf("%.1f\n", max);
    } else {
        printf("Error: Necesitas al menos dos calificaciones\n");
    }
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    int aprobaron = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double calificacion;
        scanf("%lf", &calificacion);
        if (calificacion >= 6.0) {
            aprobaron++;
        }
    }
    if (n >= 2) {
        printf("%d\n", aprobaron);
    } else {
        printf("Error: Necesitas al menos dos calificaciones\n");
    }
    return 0;
}
